from __future__ import annotations

from roberta.learning import pyramid_dashboard as dashboard


# Full-color face crop taken from the Roberta reference art used for the
# Learning Command Center. Keeping the avatar independent from the holographic
# background prevents the hologram treatment from changing Roberta's skin,
# hair, or clothing colors.
_ROBERTA_AVATAR_JPEG_B64 = (
    ""
)

_ORIGINAL_RENDER = dashboard.render_dashboard


def render_dashboard(*args: object, **kwargs: object) -> str:
    html = _ORIGINAL_RENDER(*args, **kwargs)
    avatar = (
        '<div class="avatar roberta-avatar-full-color" aria-label="Roberta avatar">'
        f'<img src="data:image/jpeg;base64,{_ROBERTA_AVATAR_JPEG_B64}" alt="Roberta">'
        '</div>'
    )
    html = html.replace(
        '<div class="avatar" aria-label="Roberta avatar"></div>',
        avatar,
        1,
    )
    avatar_css = """
<style>
.roberta-avatar-full-color {
  background: #061922 !important;
  overflow: hidden;
  isolation: isolate;
  filter: none !important;
  opacity: 1 !important;
}
.roberta-avatar-full-color img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  filter: none !important;
  opacity: 1 !important;
  mix-blend-mode: normal !important;
}
</style>
"""
    return html.replace("</head>", avatar_css + "</head>", 1)


def main() -> None:
    # DashboardHandler resolves render_dashboard from the dashboard module at
    # request time, so patch only the presentation function and retain every
    # existing read-only telemetry/health boundary.
    dashboard.render_dashboard = render_dashboard
    dashboard.main()
